import React from "react";

// ── Types ─────────────────────────────────────────────────────────────────────
export interface SkillItem {
  name: string;
  icon: React.ReactNode;
}

export interface SkillCategory {
  title: string;
  skills: SkillItem[];
}

// ── Reusable Sub-Component ───────────────────────────────────────────────────
export function SkillCard({ name, icon }: SkillItem) {
  return (
    <div className="skill-card bg-[var(--canvas-elevated)] border border-[var(--hairline)] rounded-xl p-3 flex items-center gap-3 hover:border-[var(--link)] hover:-translate-y-0.5 transition-all duration-200 cursor-default shadow-2xs">
      <div className="skill-icon w-6 h-6 shrink-0 flex items-center justify-center text-[var(--ink)]">
        {icon}
      </div>
      <span className="skill-name text-sm font-semibold text-[var(--ink)] truncate">
        {name}
      </span>
    </div>
  );
}

